package paasio

import (
	"io"
	"sync"
)

// ReadCounter is an io.Reader that can report its total bytes and operation counts.
type ReadCounter interface {
	io.Reader
	// ReadCount returns the total number of bytes and read operations.
	ReadCount() (int64, int)
}

// WriteCounter is an io.Writer that can report its total bytes and operation counts.
type WriteCounter interface {
	io.Writer
	// WriteCount returns the total number of bytes and write operations.
	WriteCount() (int64, int)
}

// ReadWriteCounter is both a ReadCounter and a WriteCounter.
type ReadWriteCounter interface {
	ReadCounter
	WriteCounter
}

type readCounter struct {
	reader io.Reader
	mu     sync.Mutex
	numBytes int64
	numOps   int
}

func NewReadCounter(reader io.Reader) ReadCounter {
	return &readCounter{reader: reader}
}

func (rc *readCounter) Read(p []byte) (int, error) {
	n, err := rc.reader.Read(p)
	rc.mu.Lock()
	rc.numBytes += int64(n)
	if n > 0 {
		rc.numOps++
	}
	rc.mu.Unlock()
	return n, err
}

func (rc *readCounter) ReadCount() (int64, int) {
	rc.mu.Lock()
	defer rc.mu.Unlock()
	return rc.numBytes, rc.numOps
}

// writeCounter is similar.

type readWriteCounter struct {
	*readCounter
	*writeCounter
}

func NewReadWriteCounter(readwriter io.ReadWriter) ReadWriteCounter {
	return &readWriteCounter{
		readCounter: NewReadCounter(readwriter).(*readCounter),
		writeCounter: NewWriteCounter(readwriter).(*writeCounter),
	}
}
